html:
{%- import "erpnext/templates/print_formats/report_print_macros.html" as rp -%}
{%- set show_company = no_letterhead if no_letterhead is defined else not letter_head -%}
{%- set rows = [] -%}
{%- for row in data if row is mapping and row.item_code and row.warehouse and not row.is_total_row and (row.bal_qty or filters.include_zero_stock_items) -%}
	{%- set ignore = rows.append(row) -%}
{%- endfor -%}
{{ rp.styles() }}
<div class="rpf">
	{%- if show_company %}{{ rp.company_header(filters.company) }}{% endif %}
	{{ rp.head(_("Warehouse Stock Summary"), _("As on {0}").format(rp.date(filters.to_date))) }}
	<table class="rpf-grid">
		<colgroup><col><col style="width: 120px"><col style="width: 112px"><col style="width: 128px"></colgroup>
		<thead>
			<tr>
				<th>{{ _("Particulars") }}</th>
				<th class="num">{{ _("Quantity") }}</th>
				<th class="num">{{ _("Rate") }}</th>
				<th class="num">{{ _("Value") }}</th>
			</tr>
		</thead>
		<tbody>
			{%- for group in rows | groupby("warehouse") %}
			<tr class="group">
				<td>{{ rp.short(group.grouper, filters.company) }} <span class="muted regular">· {{ (_("{0} item") if group.list | length == 1 else _("{0} items")).format(group.list | length) }}</span></td>
				<td></td>
				<td></td>
				<td class="num">{{ rp.money(group.list | map(attribute="bal_val") | map("float") | sum) }}</td>
			</tr>
			{%- for row in group.list | sort(attribute="item_name") %}
			<tr>
				<td class="indent">
					{{ row.item_name or row.item_code }}
					{%- if row.item_name and row.item_name != row.item_code %}<span class="muted"> · {{ row.item_code }}</span>{% endif %}
				</td>
				<td class="num">{% if row.bal_qty %}{{ rp.qty(row.bal_qty) }} <span class="muted">{{ row.stock_uom or "" }}</span>{% else %}<span class="muted">{{ _("Nil") }}</span>{% endif %}</td>
				<td class="num muted">{{ rp.money(row.val_rate) }}</td>
				<td class="num">{{ rp.money(row.bal_val) }}</td>
			</tr>
			{%- endfor %}
			{%- else %}
			<tr><td colspan="4" class="rpf-empty">{{ _("No stock in hand") }}</td></tr>
			{%- endfor %}
			{%- if rows %}
			<tr class="total">
				<td colspan="3">{{ _("Total") }}</td>
				<td class="num"><span class="double">{{ rp.money(rows | map(attribute="bal_val") | map("float") | sum) }}</span></td>
			</tr>
			{%- endif %}
		</tbody>
	</table>
	{{ rp.footnote() }}
</div>
